/* Global variables */
flag_plot_layer_automatic = true;

function addZero(i) {
    if (i < 10) {
        i = "0" + i;
    }
    return i;
}

function formatDate(inputDate) {
    var inputDateUTC   = inputDate + '+00:00';
    var date    = new Date(inputDateUTC);
    var yr      = date.getUTCFullYear();
    var month   = addZero((date.getUTCMonth()+1));
    var day     = addZero(date.getUTCDate());
    var hours    = addZero(date.getUTCHours());
    var minutes    = addZero(date.getUTCMinutes());
    var seconds    = addZero(date.getUTCSeconds());
    var outputDate = yr + '-' + month + '-' + day + ' ' + hours + ':' + minutes + ':' + seconds;
    console.debug('date:' + inputDate);
    console.debug('dateUTC:' + inputDateUTC);
    console.debug('dateNew:' + outputDate);
    return outputDate;
}


function makeIcon(feature, curClassName) {
	curClassName = (typeof curClassName === 'undefined') ? 'icon-marker' : curClassName;
    console.debug('START - makeIcon ' + curClassName);
    var myIcon = L.divIcon({className: curClassName});
    console.debug('END - makeIcon ' + curClassName);
    return myIcon;
}

function makePopoverContent(feature) {
    console.debug('START - makePopoverContent');
    var contentString = '';
    $.each(feature.properties, function(key, val){
        if(key != 'geometry') {
            contentString += '<b>' + key + '</b>' + '=' + val + '<br>';
        }
    });
    console.debug('END - makePopoverContent');
    return contentString;
}

function makeMarker(feature, latlng, curMakeIcon) {
    console.debug('START - makeMarker');
    var myIcon = curMakeIcon(feature);
    var marker = L.marker(latlng, {
        icon: myIcon, 
        zIndexOffset:5000 
    });
    console.debug('END - makeMarker');
    return marker;
}

function makeJsonLayerStyle(feature) {
    console.debug('START - makeJsonLayerStyle');
    var jsonLayerStyle = {
        color: 'blue'
    }
    console.debug('END - makeJsonLayerStyle');
    return jsonLayerStyle;
}

function makeJsonLayer(jsonData, curMakeIcon, curMakeMarker, makePopoverContentFunction, curMakeJsonLayerStyle) {
    console.debug('START - makeJsonLayer');
    var jsonLayer = L.geoJson(jsonData, {
            style: function (feature) {
                return curMakeJsonLayerStyle(feature);
            },        
            pointToLayer: function (feature, latlng) {
                return curMakeMarker(feature, latlng, curMakeIcon);
            },
            opacity: 1,
            weight: 2,
            onEachFeature: function (feature, layer) {
                var popoverContent = makePopoverContentFunction(feature);
                layer.bindPopup(popoverContent);
            }
        });
    console.debug('END - makeJsonLayer');
    return jsonLayer;
}

function addJsonLayer(jsonData, curMap, curLayersControl, layerName, curMakeIcon, curMakeMarker, curMakePopoverContentFunction, auto_zoom, curMakeJsonLayerStyle) {
    console.debug('START - addJsonLayer ' + layerName);
	var dataLayer = makeJsonLayer(jsonData, curMakeIcon, curMakeMarker, curMakePopoverContentFunction, curMakeJsonLayerStyle);
    curLayersControl.addOverlay(dataLayer, layerName);
    curMap.addLayer(dataLayer);
    if (typeof initEqTimeSlider === 'function') { try { initEqTimeSlider(dataLayer, curMap); } catch (e) { console.error(e); } }
	if(auto_zoom == 1) {
		automatic_zoom_on_layer(dataLayer);
	}
    console.debug('END - addJsonLayer ' + layerName);
}

function automatic_zoom_on_layer(curLayer) {
	if (curLayer.getLayers().length == 1) {
		console.debug('if_1');
		console.debug('getBoundsZoom:' + map.getBoundsZoom(curLayer.getBounds()));
		map.fitBounds(curLayer.getBounds());
		map.setZoom(9);        
	} else {
		console.debug('if_2');
		console.debug('getBoundsZoom:' + map.getBoundsZoom(curLayer.getBounds()));
		map.fitBounds(curLayer.getBounds());
		if (curLayer.getLayers().length == 2) {
			console.debug('if_2_1');
			map.setZoom((map.getBoundsZoom(curLayer.getBounds()) - 1));
		} else {
			console.debug('if_2_2');
		}
	}
}

function leaflet_geojson_plotter_generic(jsonParams) {
    var old_console_debug = console.debug;
    console.debug = function() {
		var map_debug_str = String(jsonParams.map_debug);
		if ( map_debug_str == "1" || map_debug_str == "true" ) {
            old_console_debug.apply(this, arguments);
        }
    }

    console.debug('START - leaflet_geojson_plotter_generic');
    // START - Setting base layer
    var esriUrl = function (p) { return 'https://server.arcgisonline.com/ArcGIS/rest/services/' + p + '/MapServer/tile/{z}/{y}/{x}'; };
    var oceanOpts = { maxNativeZoom: 10, maxZoom: 14, attribution: 'Tiles &copy; Esri, GEBCO, NOAA, National Geographic' };
    var mapStreet = L.tileLayer(esriUrl('World_Street_Map'), { maxZoom: 18, attribution: 'Tiles &copy; Esri, HERE, Garmin, OpenStreetMap contributors' });
    var mapTopo = L.tileLayer(esriUrl('World_Topo_Map'), { maxZoom: 18, attribution: 'Tiles &copy; Esri, HERE, Garmin, USGS, NGA' });
    var mapSat = L.tileLayer(esriUrl('World_Imagery'), { maxZoom: 17, attribution: 'Tiles &copy; Esri, Maxar, Earthstar Geographics' });
    var mapOcean = L.layerGroup([L.tileLayer(esriUrl('Ocean/World_Ocean_Base'), oceanOpts), L.tileLayer(esriUrl('Ocean/World_Ocean_Reference'), oceanOpts)]);
    var esriT = function (p, o) { return L.tileLayer(esriUrl(p), o); },
        esriA = function (t) { return { maxZoom: 18, attribution: 'Tiles &copy; Esri' + (t ? ', ' + t : '') }; },
        lbl = { maxNativeZoom: 13, maxZoom: 18, attribution: 'Esri' },
        osmNote = (location.protocol === 'file:') ? ' (non funziona da file locale)' : '';
    var baseMaps = {
        "Mappa stradale (Esri)": mapStreet,
        "Topografica (Esri)": mapTopo,
        "Rilievo (Esri Terrain)": L.layerGroup([esriT('World_Terrain_Base', { maxNativeZoom: 9, maxZoom: 18, attribution: 'Tiles &copy; Esri, USGS, NOAA' }), esriT('Reference/World_Reference_Overlay', lbl)]),
        "Rilievo ombreggiato (Esri)": L.layerGroup([esriT('World_Shaded_Relief', { maxNativeZoom: 12, maxZoom: 18, attribution: 'Tiles &copy; Esri, NASA, NGA, USGS' }), esriT('Reference/World_Reference_Overlay', lbl)]),
        "Fisica (Esri)": esriT('World_Physical_Map', { maxNativeZoom: 8, maxZoom: 18, attribution: 'Tiles &copy; Esri, US National Park Service' }),
        "National Geographic (Esri)": esriT('NatGeo_World_Map', { maxNativeZoom: 12, maxZoom: 18, attribution: 'Tiles &copy; Esri, National Geographic, USGS, NOAA' }),
        "Grigio chiaro (Esri)": L.layerGroup([esriT('Canvas/World_Light_Gray_Base', { maxNativeZoom: 15, maxZoom: 18, attribution: 'Tiles &copy; Esri, HERE, Garmin' }), esriT('Canvas/World_Light_Gray_Reference', { maxNativeZoom: 15, maxZoom: 18, attribution: 'Esri' })]),
        "Grigio scuro (Esri)": L.layerGroup([esriT('Canvas/World_Dark_Gray_Base', { maxNativeZoom: 15, maxZoom: 18, attribution: 'Tiles &copy; Esri, HERE, Garmin' }), esriT('Canvas/World_Dark_Gray_Reference', { maxNativeZoom: 15, maxZoom: 18, attribution: 'Esri' })]),
        "Satellite (Esri)": mapSat,
        "Satellite con nomi (Esri)": L.layerGroup([esriT('World_Imagery', { maxZoom: 18, maxNativeZoom: 17, attribution: 'Tiles &copy; Esri, Maxar, Earthstar Geographics' }), esriT('Reference/World_Boundaries_and_Places', lbl)]),
        "Batimetria (Esri Ocean)": mapOcean,
        "Blue Marble, rilievo e batimetria (NASA)": L.tileLayer('https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/BlueMarble_ShadedRelief_Bathymetry/default/GoogleMapsCompatible_Level8/{z}/{y}/{x}.jpeg', { maxNativeZoom: 8, maxZoom: 18, attribution: 'Imagery &copy; NASA EOSDIS GIBS' }),
        "OpenTopoMap (dati OpenStreetMap)": L.tileLayer('https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png', { subdomains: 'abc', maxNativeZoom: 17, maxZoom: 18, attribution: '&copy; OpenStreetMap contributors, SRTM, &copy; OpenTopoMap (CC-BY-SA)' }),
        "OpenStreetMap Francia": L.tileLayer('https://{s}.tile.openstreetmap.fr/osmfr/{z}/{x}/{y}.png', { subdomains: 'abc', maxZoom: 18, attribution: '&copy; OpenStreetMap contributors, tiles OSM France' }),
        "OpenStreetMap umanitaria (HOT)": L.tileLayer('https://{s}.tile.openstreetmap.fr/hot/{z}/{x}/{y}.png', { subdomains: 'abc', maxZoom: 18, attribution: '&copy; OpenStreetMap contributors, tiles HOT / OSM France' })
    };
    baseMaps["OpenStreetMap" + osmNote] = L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 18, attribution: '&copy; OpenStreetMap contributors' });
    // END - Setting base layers object
    
    // START - Setting complex layers object
    var complexMaps = { }    
    // END - Setting complex layers object
    
    // START - Setting and building Map
    var mapOptions = {
        zoom: jsonParams.map_zoom,
        center: [jsonParams.map_center_lat, jsonParams.map_center_lon],
        scrollWheelZoom: false,
        layers: [mapStreet],
        zoomControl: false
    }
    
    var staleMap = document.getElementById('map'); if (staleMap) { staleMap.innerHTML = ''; }
    map = new L.map('map', mapOptions);
    layersControl = L.control.layers(baseMaps, complexMaps).addTo(map);
    
    // scale
    var mapScale = L.control.scale({maxWidth:100});
    mapScale.addTo(map);
    
    //zoom control
    var mapZoomControl = L.control.zoom({position:'topleft'});
    mapZoomControl.addTo(map);    
    // END - Setting and building Map
    
    // START - Setting complex layer
    // var jsonLayer = makeJsonLayer(jsonParams.geojsonEncodedVariable, makeIcon, makeMarker, makePopoverContent);
    // layersControl.addOverlay(jsonLayer, 'layer');
    // map.addLayer(jsonLayer);
    // END - Setting complex layer

    // START - Leaflet coordinates plug-in
    L.control.coordinates({
                            position:"bottomright",
                            decimals:2,
                            decimalSeperator:".",
                            labelTemplateLat:"Lat: {y}",
                            labelTemplateLng:"Lon: {x}",
                            enableUserInput: false,
                            useLatLngOrder: true,
                    }).addTo(map);
    // END - Leaflet coordinates plug-in
    
    console.debug('END - leaflet_geojson_plotter_generic');
};




