function eqLoadPrefs() {
    var P = {}, k, saved = {};
    try { saved = JSON.parse(localStorage.getItem('eqINGVprefs') || '{}') || {}; } catch (e) { saved = {}; }
    for (k in EQ_DEFAULTS) { P[k] = (saved[k] !== undefined && typeof saved[k] === typeof EQ_DEFAULTS[k]) ? saved[k] : EQ_DEFAULTS[k]; }
    return P;
}
