function eqPolarity(strike, dip, rake, az, inc) {
    /* > 0: compressione (primo moto in alto). Angoli in radianti; assi Nord, Est, Giu (Aki e Richards) */
    var cf = Math.cos(strike), sf = Math.sin(strike), cd = Math.cos(dip), sd = Math.sin(dip), cl = Math.cos(rake), sl = Math.sin(rake),
        nx = -sd * sf, ny = sd * cf, nz = -cd,
        dx = cl * cf + cd * sl * sf, dy = cl * sf - cd * sl * cf, dz = -sl * sd,
        rx = Math.sin(inc) * Math.cos(az), ry = Math.sin(inc) * Math.sin(az), rz = Math.cos(inc);
    return (rx * nx + ry * ny + rz * nz) * (rx * dx + ry * dy + rz * dz);
}
var EQ_BB_CACHE = {};
function eqBeachball(fm, size, color) {
    var key = [fm.s1, fm.d1, fm.r1, size, color].join('_'), cv, ctx, img, R = size / 2, x, y, px, py, rho, k, comp, rgb, r0, g0, b0, S, D, Rk, rad = Math.PI / 180;
    if (EQ_BB_CACHE[key]) { return EQ_BB_CACHE[key]; }
    cv = document.createElement('canvas'); cv.width = size; cv.height = size;
    ctx = cv.getContext('2d'); img = ctx.createImageData(size, size);
    rgb = parseInt(color.slice(1), 16); r0 = rgb >> 16; g0 = (rgb >> 8) & 255; b0 = rgb & 255;
    S = fm.s1 * rad; D = fm.d1 * rad; Rk = fm.r1 * rad;
    for (y = 0; y < size; y++) {
        for (x = 0; x < size; x++) {
            px = (x + 0.5 - R) / R; py = (R - y - 0.5) / R; rho = Math.sqrt(px * px + py * py); k = (y * size + x) * 4;
            if (rho > 1) { img.data[k + 3] = 0; continue; }
            comp = eqPolarity(S, D, Rk, Math.atan2(px, py), 2 * Math.asin(Math.min(1, rho / Math.SQRT2))) > 0;
            img.data[k] = comp ? r0 : 255; img.data[k + 1] = comp ? g0 : 255; img.data[k + 2] = comp ? b0 : 255; img.data[k + 3] = 255;
        }
    }
    ctx.putImageData(img, 0, 0);
    EQ_BB_CACHE[key] = cv;
    return cv;
}
function eqParsePsmeca(text) {
    /* righe "lon lat prof strike1 dip1 rake1 strike2 dip2 rake2 mantissa esponente [x y]", con ID evento facoltativo davanti */
    var out = [], lines = String(text).split(/\r?\n/), i, t, id, mm, n, m0;
    for (i = 0; i < lines.length; i++) {
        t = lines[i].replace(/[;,|]/g, ' ').trim();
        if (!t) { continue; }
        id = null; mm = t.match(/^(\d{6,})\s*:?\s+(.*)$/);
        if (mm && mm[2].split(/\s+/).length >= 11) { id = mm[1]; t = mm[2]; }
        n = t.split(/\s+/).map(Number);
        if (n.length < 11 || n.slice(0, 11).some(isNaN) || n[9] <= 0) { continue; }
        m0 = n[9] * Math.pow(10, n[10]);
        out.push({ id: id, lon: n[0], lat: n[1], depth: n[2], s1: n[3], d1: n[4], r1: n[5], s2: n[6], d2: n[7], r2: n[8], mant: n[9], exp: n[10], m0: m0, mw: (Math.log(m0) / Math.LN10 - 16.1) * 2 / 3 });
    }
    return out;
}
function eqKind(rake) {
    var r = ((rake + 540) % 360) - 180;
    if (r > 45 && r < 135) { return 'inversa (compressivo)'; }
    if (r < -45 && r > -135) { return 'normale (distensivo)'; }
    return 'trascorrente';
}
function eqParseQuakeML(txt) {
    /* meccanismo focale dal QuakeML dell'INGV; null se non presente */
    function v(el, name) {
        var e = el && el.getElementsByTagNameNS('*', name)[0], x = e && e.getElementsByTagNameNS('*', 'value')[0];
        return x ? parseFloat(x.textContent) : NaN;
    }
    try {
        var doc = new DOMParser().parseFromString(txt, 'text/xml'), fms = doc.getElementsByTagNameNS('*', 'focalMechanism'), fe = null, j, pref, pid, p1, p2, mt, m0, dep = NaN, did, os, o;
        if (!fms.length) { return null; }
        pref = doc.getElementsByTagNameNS('*', 'preferredFocalMechanismID')[0]; pid = pref ? pref.textContent.trim() : '';
        for (j = 0; j < fms.length; j++) { if (fms[j].getAttribute('publicID') === pid) { fe = fms[j]; } }
        if (!fe) { fe = fms[0]; }
        p1 = fe.getElementsByTagNameNS('*', 'nodalPlane1')[0]; p2 = fe.getElementsByTagNameNS('*', 'nodalPlane2')[0];
        if (!p1) { return null; }
        o = { s1: v(p1, 'strike'), d1: v(p1, 'dip'), r1: v(p1, 'rake'), s2: v(p2, 'strike'), d2: v(p2, 'dip'), r2: v(p2, 'rake') };
        if (isNaN(o.s1) || isNaN(o.d1) || isNaN(o.r1)) { return null; }
        mt = fe.getElementsByTagNameNS('*', 'momentTensor')[0]; m0 = mt ? v(mt, 'scalarMoment') : NaN;
        o.m0 = m0 * 1e7; o.mw = (Math.log(m0) / Math.LN10 - 9.1) * 2 / 3;
        did = mt && mt.getElementsByTagNameNS('*', 'derivedOriginID')[0];
        if (did) {
            os = doc.getElementsByTagNameNS('*', 'origin');
            for (j = 0; j < os.length; j++) { if (os[j].getAttribute('publicID') === did.textContent.trim()) { dep = v(os[j], 'depth') / 1000; } }
        }
        o.depth = dep;
        return o;
    } catch (e) { return null; }
}
